import enum

from .Ages import Age2AgeData
from .Buildings import Age2BuildingData


from ..items.Items import Age2ItemData

class TechOption:
    units = "Units"
    generic = "Generic"
    unique = "Unique"
    regional = "Regional"

@enum.unique
class Age2TechData(enum.IntEnum):

    def __new__(cls, id: int, *args, **kwargs):
        value = id
        obj = int.__new__(cls, value)
        obj._value_ = value
        return obj

    def __init__(
        self, id: int, location_name: str, item: Age2ItemData, age: Age2AgeData,
        tech_options: list[TechOption], buildings: list[Age2BuildingData],
        prerequisite: str
    ) -> None:
        self.id = id
        self.location_name = location_name
        self.item = item
        self.age = age
        self.tech_options = tech_options
        self.buildings = buildings
        self._prerequisite = prerequisite

    @property
    def prerequisite(self) -> 'Age2TechData':
        return Age2TechData[self._prerequisite] if self._prerequisite else None

    @property
    def prerequisiteId(self) -> int:
        return self.prerequisite.item.type.game_id if self._prerequisite else -1

